        let len: Int32 = try readInt(&buf)
        var seq = [XboxGame]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeXboxGame.read(from: &buf))
        }
        return seq
    }
}

